794		simd_mul16x16(&(tmp[ 32 ]), &(modn[ 32 ]), &(inv[ 32 ]));
795		simd_mul16x16(&(tmp[ 48 ]), &(modn[ 48 ]), &(inv[ 48 ]));
796	
797						// any of the products <= limit[ ]?
798						// divides -> ffff; not -> 0
799	
800		simd_lemask16x16_inpl(  tmp,          limit       );
801		simd_lemask16x16_inpl(&(tmp[ 16 ]), &(limit[ 16 ]));
802		simd_lemask16x16_inpl(&(tmp[ 32 ]), &(limit[ 32 ]));
803		simd_lemask16x16_inpl(&(tmp[ 48 ]), &(limit[ 48 ]));
804	
805		return simd_is_all0x64x16_inpl(tmp, tmp2);
806	}
