666	// note: zero-flag (ZF) checking for 256-bit wide SIMD units
667	// above, we rely on the all-0 16x16-bit representation 
668	//
669	// there are equivalent intrinsics, or even the straightforward AND-all
670	// of 16x16 bits may turn into a short construct. TBD
671	//
672	#if 0
673	#if (SYS__X86_BITS >= 64)
674		return _mm256_testz_si256((const __m256i) *v, (const __m256i) *v);
675			// 
676			// compare-all-0 compiles into vpxor, vptest "close enough"
677	
678	#elif (SYS__AARCH >= 64)
679		return (vmaxvq_u16(v) == 0);
680			// MAX(..16x16 bits..); does not require use of all-0
681			// aux. register
682			//
683			// compiles into:
684			//     umaxv hd,vn.8h   "Unsigned Maximum across Vector"
685			//
686			// see developer.arm.com/architectures/instruction-sets/
687			//     intrinsics/vmaxvq_u16
688	
689	#elif (SYS__S390_BITS >= 64)
690	#error "supply S390 check-ZF(compare-0) intrinsic here"
691	
692	#else
693		return !!((((v[  0 ] | v[  1 ]) | (v[  2 ] | v[  3 ]))  &
694		           ((v[  4 ] | v[  5 ]) | (v[  6 ] | v[  7 ]))) &
695		          (((v[  8 ] | v[  9 ]) | (v[ 10 ] | v[ 11 ]))  &
696		           ((v[ 12 ] | v[ 13 ]) | (v[ 14 ] | v[ 15 ]))));
697			// note the 8x2 split
698			// expect to be specialized into faster-than-16x expression
699	
700	#endif
701	#endif
702	#endif       // /256 bits
