705	/*-----------------------------------------
706	 * is 64x16 wide SIMD array all zeroes?
707	 *
708	 * SECURITY NOTE: tmp[] is scratch which caller MUST wipe
709	 * NOTE: DESTROYS ORIGINAL INPUTS
710	 */
711	static inline
712	REALLY_FORCE_INLINE
713	/**/
714	unsigned int simd_is_all0x64x16_inpl(uint16_t v[static 64],
715	                                   uint16_t tmp[static 16])
716	{
717		simd_or16x16(tmp, &(v[32]), &(v[48]));       // 2 3
718		simd_or16x16(v,     v,      &(v[16]));       // 0 1
719		simd_or16x16(v,     tmp,      v     );       // 0 1 2 3
720	
721		return simd_is_all0(v);
722	}
