725	/*-----------------------------------------
726	 * v[] += adv; preserving mod-prime by subtracting m2r[] if applicable
727	 */
728	static inline
729	REALLY_FORCE_INLINE
730	/**/
731	void simd_advance64x16_m2r_inpl(uint16_t v[static 64], uint16_t adv,
732	                        const uint16_t m2r[static 64])
733	{
734		simd_advance16x16_inpl(  v,          adv       );
735		simd_m2range16x16_inpl(  v,          m2r       );
736	
737		simd_advance16x16_inpl(&(v[ 16 ]),   adv       );
738		simd_m2range16x16_inpl(&(v[ 16 ]), &(m2r[ 16 ]));
739	
740		simd_advance16x16_inpl(&(v[ 32 ]),   adv       );
741		simd_m2range16x16_inpl(&(v[ 32 ]), &(m2r[ 32 ]));
742	
743		simd_advance16x16_inpl(&(v[ 48 ]),   adv       );
744		simd_m2range16x16_inpl(&(v[ 48 ]), &(m2r[ 48 ]));
745	}
