775	/*-----------------------------------------
776	 * 'plain' prime search: can modn[] indicate a prime?
777	 *
778	 * SECURITY NOTE: tmp[] and tmp2[] are scratch, filled with (potentially)secret
779	 * state-dependent data, and SHOULD be wiped upon return.
780	 */
781	static inline
782	REALLY_FORCE_INLINE
783	/**/
784	uint16_t simd_nofactor64x16(uint16_t tmp[static 64],
785	                           uint16_t tmp2[static 64],
786	                     const uint16_t modn[static 64],
787	                      const uint16_t inv[static 64],
788	                    const uint16_t limit[static 64])
789	{
790						// compute n * 1/prime  mod 2^16
791	
792		simd_mul16x16(  tmp,          modn,          inv       );
793		simd_mul16x16(&(tmp[ 16 ]), &(modn[ 16 ]), &(inv[ 16 ]));
794		simd_mul16x16(&(tmp[ 32 ]), &(modn[ 32 ]), &(inv[ 32 ]));
795		simd_mul16x16(&(tmp[ 48 ]), &(modn[ 48 ]), &(inv[ 48 ]));
796	
797						// any of the products <= limit[ ]?
798						// divides -> ffff; not -> 0
799	
800		simd_lemask16x16_inpl(  tmp,          limit       );
801		simd_lemask16x16_inpl(&(tmp[ 16 ]), &(limit[ 16 ]));
802		simd_lemask16x16_inpl(&(tmp[ 32 ]), &(limit[ 32 ]));
803		simd_lemask16x16_inpl(&(tmp[ 48 ]), &(limit[ 48 ]));
804	
805		return simd_is_all0x64x16_inpl(tmp, tmp2);
806	}
