809	/*--------------------------------------
810	 * does the first set of prime moduli (64 primes) indicate prime?
811	 *
812	 * SECURITY NOTE: tmp[] and tmp2[] are scratch areas, which caller
813	 * MUST maintain and wipe
814	 */
815	static inline
816	REALLY_FORCE_INLINE
817	/**/
818	uint16_t simd_nofactor_first(uint16_t tmp[static 64],
819	                             uint16_t tm2[static 64],
820	             const struct PP_Mod16bit *ps)
821	{
822		return simd_nofactor64x16(tmp, tm2, ps->modn,
823		                          firstprimes_inverse_simd,
824		                          firstprimes_mullimit_simd);
825	}
